def main():
    out=ROOT/"data"/"manuals"; out.mkdir(parents=True,exist_ok=True)
    for name, sections in MANUALS.items():
        doc=fitz.open()
        for heading, body in sections:
            page=doc.new_page(); page.insert_text((54,50),"EDGEFIX AI  /  SYNTHETIC TRAINING MATERIAL",fontsize=9,color=(0.15,0.45,0.35))
            page.insert_textbox(fitz.Rect(54,78,540,120),heading,fontsize=19,fontname="helv",color=(0.08,0.15,0.2))
            page.insert_textbox(fitz.Rect(54,137,540,720),body,fontsize=11,fontname="helv",lineheight=1.45)
            page.insert_text((54,760),"Original synthetic content · Not manufacturer guidance",fontsize=8,color=(0.35,0.4,0.42))
        doc.set_metadata({"title":name.removesuffix(".pdf").replace("_"," "),"author":"EdgeFix AI synthetic sample knowledge base","subject":"Original fictional training material"})
        doc.save(out/name); doc.close(); print(f"Created {name}")

if __name__=="__main__": main()
